tool_input.command:
cat > test-custom-metric.mjs << 'EOF'
import { Eval } from './packages/frai-core/dist/index.js';

const customMetric = (outputs, references) => ({
  id: 'custom_score',
  label: 'Custom Score',
  score: 0.85,
  total: outputs.length
});

const evaluations = Eval.runEvaluations({
  outputs: ['hello', 'world'],
  references: ['hello', 'world'],
  metrics: [Eval.exactMatchMetric, customMetric]
});

const report = Eval.generateReport({
  evaluations,
  outputsPath: '/tmp/outputs.json',
  referencesPath: '/tmp/refs.json',
  thresholds: { exact_match: 1.0, custom_score: 0.8 }
});

console.log('Report passed:', report.passed);
console.log('Thresholds:', JSON.stringify(report.thresholds, null, 2));
EOF
node test-custom-metric.mjs 2>&1 | head -20
